steps.run:
set -euo pipefail
node --input-type=module <<'NODE'
import { VERBS, resolveVerb } from './plugins/omniroute-broker/dist/verbs.js'
const forbiddenNames = [
  'keys.create', 'keys.reveal', 'keys.regenerate', 'keys.rotate',
  'cli.tokens.create', 'cli.tokens.mint',
]
for (const name of forbiddenNames) {
  if (Object.hasOwn(VERBS, name)) throw new Error(`forbidden verb exists: ${name}`)
  try { resolveVerb(name); throw new Error(`forbidden verb resolved: ${name}`) }
  catch (error) { if (error.status !== 404) throw error }
}
const forbiddenPaths = ['/api/keys', '/api/cli/tokens']
for (const [name, verb] of Object.entries(VERBS)) {
  for (const path of forbiddenPaths) {
    if (verb.path === path || verb.path.startsWith(`${path}/`)) {
      throw new Error(`${name} reaches forbidden credential path ${verb.path}`)
    }
  }
}
console.log('credential mint, reveal and regeneration surfaces: absent')
NODE

